<template>
  <Teleport to="body">
    <dialog ref="dialog" class="visit-dialog" :class="{'is-dark':dark}" aria-labelledby="visit-dialog-title" @cancel.prevent="dismiss" @keydown.stop @click="backdrop">
      <form class="visit-card" @submit.prevent="submit">
        <button class="visit-dismiss" type="button" aria-label="Leave without submitting" :disabled="busy" @click="dismiss"><svg viewBox="0 0 20 20" aria-hidden="true"><path d="m5 5 10 10M15 5 5 15"/></svg></button>
        <GalleryMark class="visit-mark"/>
        <h2 id="visit-dialog-title">How was your visit?</h2>
        <p class="visit-intro">Your feedback helps me improve the exhibitions.</p>
        <fieldset class="visit-stars" :disabled="busy"><legend class="visit-sr">Rate your visit</legend>
          <label v-for="n in 5" :key="n" :class="{'is-filled':n <= (hovered || rating)}" @mouseenter="hovered=n" @mouseleave="hovered=0">
            <input v-model="rating" type="radio" name="visit-rating" :value="n" :aria-label="`${n} ${n===1?'star':'stars'}`"/>
            <svg viewBox="0 0 24 24" aria-hidden="true"><path d="m12 3 2.8 5.7 6.3.9-4.55 4.45 1.07 6.28L12 17.36l-5.62 2.97 1.07-6.28L2.9 9.6l6.3-.9Z"/></svg>
          </label>
        </fieldset>
        <label class="visit-feedback-label" for="visit-feedback">A note to Henry <span>Optional</span></label>
        <textarea id="visit-feedback" v-model="text" :disabled="busy" maxlength="1200" rows="3" placeholder="What worked for you? What could be better?"></textarea>
        <p class="visit-private">Only Henry can read this feedback and its approximate country and device details.</p>
        <label v-if="canPublish && !published" class="visit-publish"><input v-model="makePublic" :disabled="busy" type="checkbox"/><span>Share this exhibition in the Gallery<small>Other visitors can find and explore the View you created.</small></span></label>
        <p v-if="published" class="visit-private">Your exhibition is now public.</p>
        <p v-if="error" class="visit-error" role="alert">{{error}}</p>
        <div class="visit-actions"><button class="visit-skip" type="button" :disabled="busy" @click="dismiss">Skip</button><button class="visit-submit" type="submit" :disabled="busy || (!!text.trim() && !rating)">{{busy?'Saving…':submitLabel}}</button></div>
      </form>
    </dialog>
  </Teleport>
</template>
<script>
import { rememberExhibitionFeedback } from '../../utils/viewMuseumSession';
import GalleryMark from './GalleryMark.vue';
import { publishSharedView, submitExhibitionFeedback } from '../../utils/viewShareSite';
export default {
  components:{GalleryMark},props:{shareId:String,canPublish:Boolean,dark:Boolean},emits:['close','published'],
  data:()=>({rating:0,hovered:0,text:'',makePublic:true,published:false,busy:false,error:'',submissionId:crypto.randomUUID().replace(/-/g,'')}),
  computed:{submitLabel(){return this.canPublish&&this.makePublic&&!this.published?'Share and leave':this.rating?'Send and leave':'Leave';}},
  mounted(){this.$refs.dialog.showModal();},beforeUnmount(){this.$refs.dialog?.close();},
  methods:{
    dismiss(){if(this.busy||this._closing)return;this._closing=true;this.$emit('close');},
    backdrop(event){if(event.target===this.$refs.dialog)this.dismiss();},
    async submit(){
      if(this.busy)return;if(this.text.trim()&&!this.rating)return;
      this.busy=true;this.error='';
      try {
        if(this.canPublish&&this.makePublic&&!this.published){await publishSharedView(this.shareId);this.published=true;this.$emit('published');}
        if(this.rating){await submitExhibitionFeedback(this.shareId,{id:this.submissionId,rating:this.rating,text:this.text});rememberExhibitionFeedback(this.shareId);}
        this.busy=false;await this.dismiss();
      }catch{this.error=this.published?'Your exhibition is public. The feedback could not be saved. Try again or skip.':'This could not be saved. Please try again, or skip to leave.';this.busy=false;}
    },
  },
};
</script>
<style scoped>
.visit-dialog{--visit-paper:#f5f3ee;--visit-ink:#373c35;--visit-muted:#777b70;box-sizing:border-box;width:min(440px,calc(100vw - 32px));max-height:calc(100dvh - 40px);padding:0;border:1px solid #858b7133;border-radius:4px;background:var(--visit-paper);color:var(--visit-ink);overflow:auto;font:15px/1.5 'Quattrocento Sans',sans-serif;animation:visit-arrive 260ms ease-out both;}
.visit-dialog.is-dark{--visit-paper:#292c28;--visit-ink:#e8e6de;--visit-muted:#a5ab9e;}
.visit-dialog::backdrop{background:#1017136b;backdrop-filter:blur(6px);animation:visit-arrive 260ms ease-out both;}
.visit-card{padding:32px;position:relative;}.visit-mark{width:32px;height:32px;color:var(--visit-muted);}
.visit-card h2{font:400 30px/1.1 'EB Garamond',Georgia,serif;margin:20px 0 10px;}.visit-intro{color:var(--visit-muted);margin:0;}
.visit-dismiss{position:absolute;top:14px;right:14px;padding:8px;border:0;background:none;color:var(--visit-muted);}.visit-dismiss svg{width:18px;height:18px;fill:none;stroke:currentColor;stroke-width:1.3;}
.visit-stars{display:flex;gap:8px;border:0;padding:0;margin:22px 0;}.visit-stars label{position:relative;width:36px;height:40px;display:grid;place-items:center;cursor:pointer;}.visit-stars input{position:absolute;opacity:0;width:100%;height:100%;margin:0;cursor:inherit;}.visit-stars svg{width:28px;height:28px;stroke:var(--visit-muted);stroke-width:1;fill:transparent;pointer-events:none;transition:fill 120ms,color 120ms;}.visit-stars .is-filled svg{fill:#a58b59;stroke:#a58b59;}.visit-stars label:has(:focus-visible){outline:1px solid currentColor;outline-offset:3px;}
.visit-sr{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%);}.visit-feedback-label{display:flex;justify-content:space-between;margin-bottom:8px;}.visit-feedback-label span,.visit-private{color:var(--visit-muted);font-size:12px;}.visit-card textarea{box-sizing:border-box;width:100%;resize:vertical;min-height:84px;max-height:160px;padding:10px 12px;border:1px solid #858b7155;border-radius:2px;background:transparent;color:inherit;font:inherit;}.visit-card textarea:focus-visible{outline:1px solid var(--visit-muted);outline-offset:2px;}.visit-private{margin:6px 0 0;}.visit-publish{display:flex;gap:10px;align-items:start;margin-top:24px;}.visit-publish input{accent-color:#6f795f;margin:4px 0 0;}.visit-publish small{display:block;color:var(--visit-muted);font-size:12px;line-height:1.5;margin-top:4px;}.visit-actions{display:flex;align-items:center;justify-content:space-between;gap:20px;margin-top:28px;}.visit-actions button{font:inherit;border:0;cursor:pointer;}.visit-skip{color:var(--visit-muted);background:none;padding:10px 0;}.visit-submit{background:var(--visit-ink);color:var(--visit-paper);padding:10px 18px;border-radius:2px;}.visit-card button:disabled{opacity:.5;cursor:default;}.visit-error{font-size:13px;color:var(--visit-ink);}.visit-card button:focus-visible{outline:1px solid var(--visit-muted);outline-offset:4px;}@keyframes visit-arrive{from{opacity:0}to{opacity:1}}@media(max-width:500px){.visit-card{padding:26px;}}@media(prefers-reduced-motion:reduce){.visit-dialog,.visit-dialog::backdrop{animation:none;}}
</style>
