function fallbackSegments(text) {
  const parts = String(text || '').match(/[\p{L}\p{N}\p{M}]+(?:[’'][\p{L}\p{N}\p{M}]+)*|[^\p{L}\p{N}\p{M}]+/gu) || [];
  return parts.map(value => ({ text:value, isWordLike:/[\p{L}\p{N}\p{M}]/u.test(value) }));
}

export function exhibitionSpeechSegments(text, language = '') {
  const value = String(text || '');
  let segments;
  try {
    const segmenter = new Intl.Segmenter(language || undefined, { granularity:'word' });
    segments = [...segmenter.segment(value)].map(part => ({ text:part.segment, isWordLike:part.isWordLike }));
  } catch { segments = fallbackSegments(value); }
  let wordIndex = -1;
  return segments.map(segment => ({ ...segment, wordIndex:segment.isWordLike ? ++wordIndex : -1 }));
}

export function exhibitionSpeechWordAt(text, progress, language = '') {
  const words = exhibitionSpeechSegments(text, language).filter(segment => segment.isWordLike);
  if (!words.length) return -1;
  const bounded = Math.max(0, Math.min(1, Number(progress) || 0));
  return Math.min(words.length - 1, Math.floor(bounded * words.length));
}

// Streaming MP3s can report Infinity until the final frame arrives. Keep the
// reading cursor moving during that interval, then use the measured duration.
// Timing is estimated from playback, not provider-supplied word alignment.
export function exhibitionSpeechProgress(text, currentTime, duration, language = '') {
  const count = exhibitionSpeechSegments(text, language).filter(segment => segment.isWordLike).length;
  const seconds = Number.isFinite(duration) && duration > 0 ? duration : Math.max(1, count / 2.5);
  return Math.max(0, Math.min(Number.isFinite(duration) ? 1 : .97, (currentTime || 0) / seconds));
}
